  v_root = aipl_fn_getAiplHomeDir();
  v_srcBin = (aipl_truthy(aipl_fn_fileExists(aipl_str_n("bin/aipl", 8))) ? aipl_str_n("bin/aipl", 8) : aipl_fn_pathJoin(v_root, aipl_str_n("bin/aipl", 8)));
